def rrf(lists: list[list[str]], k: int = 60) -> list[tuple[str, float]]:
    scores: dict[str, float] = {}
    for ranked in lists:
        for rank, doc_id in enumerate(ranked, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda x: x[1], reverse=True)

def select_mmr(candidates, query_scores, pairwise_similarity, limit, lambda_=0.7):
    selected = []
    while candidates and len(selected) < limit:
        def score(c):
            redundancy = max((pairwise_similarity(c, s) for s in selected), default=0.0)
            return lambda_ * query_scores[c] - (1 - lambda_) * redundancy
        best = max(candidates, key=score)
        selected.append(best)
        candidates.remove(best)
    return selected

